export interface TrackPoint {
  x: number;
  y: number;
  angle?: number;
  sector?: 1 | 2 | 3;
}

export interface TurnMarker {
  number: number;
  name: string;
  x: number;
  y: number;
  sector: 1 | 2 | 3;
  type: "hairpin" | "chicane" | "high_speed" | "banked" | "entry" | "medium";
}

export interface SectorDefinition {
  id: 1 | 2 | 3;
  name: string;
  description: string;
  color: string;
  bgLight: string;
  turnRange: string;
  lengthKm: number;
  baseTimeSec: number;
}

